<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import HrmsLayout from '@/Layouts/HrmsLayout.vue';
const props = defineProps({ employees:Array, periods:Array, criteria:Array, reviews:Array, canManagePeriods:Boolean });
const show = ref(false), showPeriod = ref(false);
const form = useForm({ employee_id:'', review_period_id:props.periods[0]?.id || '', summary:'', scores:props.criteria.map(c=>({criterion_id:c.id,score:3,comment:''})) });
const periodForm = useForm({ name:'', frequency:'quarterly', starts_on:'', ends_on:'' });
const save = () => form.post(route('performance.store'),{onSuccess:()=>{show.value=false;form.reset();}});
const savePeriod = () => periodForm.post(route('performance.periods.store'),{onSuccess:()=>{showPeriod.value=false;periodForm.reset();}});
</script>
<template><Head title="التقييم" /><HrmsLayout title="تقييم الأداء" subtitle="مراجعات ربع سنوية وسنوية بمعايير واضحة."><template #actions><div class="flex flex-wrap gap-2"><button v-if="canManagePeriods" class="btn-secondary" @click="showPeriod=!showPeriod">فترة تقييم جديدة</button><button class="btn-primary" @click="show=!show">تقييم جديد</button></div></template>
    <section v-if="showPeriod && canManagePeriods" class="panel mb-6 p-5 sm:p-6"><h2 class="mb-5 text-xl font-bold text-[#1F3A5F]">إنشاء فترة تقييم</h2><form @submit.prevent="savePeriod" class="grid gap-4 sm:grid-cols-2"><div><label class="label" for="period_name">اسم الفترة</label><input id="period_name" v-model.trim="periodForm.name" class="field" required></div><div><label class="label" for="frequency">نوع المراجعة</label><select id="frequency" v-model="periodForm.frequency" class="field"><option value="quarterly">ربع سنوية</option><option value="annual">سنوية</option></select></div><div><label class="label" for="period_start">من تاريخ</label><input id="period_start" type="date" v-model="periodForm.starts_on" class="field" required></div><div><label class="label" for="period_end">إلى تاريخ</label><input id="period_end" type="date" v-model="periodForm.ends_on" class="field" required></div><p v-if="Object.keys(periodForm.errors).length" class="error sm:col-span-2">{{ Object.values(periodForm.errors)[0] }}</p><div class="sm:col-span-2"><button class="btn-primary" :disabled="periodForm.processing">حفظ الفترة</button></div></form></section>
    <section v-if="show" class="panel mb-6 p-5 sm:p-6"><h2 class="mb-5 text-xl font-bold text-[#1F3A5F]">إعداد تقييم</h2><form @submit.prevent="save" class="space-y-5"><div class="grid gap-4 sm:grid-cols-2"><div><label class="label" for="employee">الموظف</label><select id="employee" v-model="form.employee_id" class="field" required><option value="">اختر موظفًا</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.first_name }} {{ e.last_name }}</option></select><p v-if="form.errors.employee_id" class="error">{{ form.errors.employee_id }}</p></div><div><label class="label" for="period">فترة المراجعة</label><select id="period" v-model="form.review_period_id" class="field" required><option v-for="p in periods" :key="p.id" :value="p.id">{{ p.name }}</option></select></div></div><div class="border-t border-slate-100 pt-5"><h3 class="mb-4 font-bold text-[#1F3A5F]">درجات المعايير</h3><div class="grid gap-3 sm:grid-cols-2"><div v-for="(score,index) in form.scores" :key="score.criterion_id" class="rounded-lg border border-slate-200 p-4"><label class="label" :for="`score-${index}`">{{ criteria[index]?.label }}</label><select :id="`score-${index}`" v-model.number="score.score" class="field"><option v-for="n in criteria[index]?.max_score || 5" :key="n" :value="n">{{ n }} من {{ criteria[index]?.max_score }}</option></select><input v-model.trim="score.comment" class="field mt-2" placeholder="ملاحظة موجزة (اختيارية)"></div></div></div><div><label class="label" for="summary">ملخص التقييم</label><textarea id="summary" v-model.trim="form.summary" rows="3" class="field"></textarea></div><p v-if="Object.keys(form.errors).length" class="error">{{ Object.values(form.errors)[0] }}</p><button class="btn-primary" :disabled="form.processing">حفظ التقييم</button></form></section>
    <section class="panel overflow-hidden"><div class="border-b border-slate-100 px-5 py-4"><h2 class="text-lg font-bold text-[#1F3A5F]">التقييمات المسجلة</h2></div><div v-for="review in reviews" :key="review.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-5 py-4 last:border-0"><div><div class="font-semibold">{{ review.employee?.first_name }} {{ review.employee?.last_name }}</div><div class="mt-1 text-xs text-slate-500">{{ review.period?.name }} · بواسطة {{ review.reviewer?.first_name }} {{ review.reviewer?.last_name }}</div><p v-if="review.summary" class="mt-2 text-sm text-slate-600">{{ review.summary }}</p></div><div class="rounded-lg bg-[#E9F3F4] px-4 py-3 text-center"><div class="text-2xl font-bold text-teal-800">{{ review.overall_score }}</div><div class="text-xs text-teal-700">من 5</div></div></div><p v-if="!reviews.length" class="p-6 text-sm text-slate-500">لا توجد تقييمات لهذه الفترة بعد.</p></section>
</HrmsLayout></template>
